// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint64 warpTs, uint256 rollNum) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.warp(warpTs);
        vm.roll(rollNum);
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;
        assertTrue(random == 0 ? c.pot() == 0 : c.pot() == 10);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test() public {
        uint amt = c.TICKET_AMOUNT();
        require(address(this).balance >= amt);
        (bool ok, ) = address(c).call{value: amt}(
            abi.encodeWithSelector(c.play.selector)
        );
        assert(ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function twoPlays(uint ticket) public {
        require(ticket > 0);
        require(address(this).balance >= 2 * ticket);
        c.play{value: ticket}();
        c.play{value: ticket}();
        assert(c.pot() <= ticket);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public {
        require(amount == 10);
        require(address(this).balance >= 3 * amount);

        c.play{value: amount}();
        c.play{value: amount}();

        uint p0 = c.pot();
        uint b2 = address(this).balance;

        c.play{value: amount}();
        uint b3 = address(this).balance;

        // On a win the payout is pot(including this call) - fee => delta = p0 - 1;
        // on a loss the delta is -amount.
        assert(b3 - b2 == p0 - 1 || b3 - b2 == -10);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function rejectNonTicketPayment(uint amount) external {
        require(amount != 10);
        require(address(this).balance >= amount);
        bool ok;
        bytes memory data;
        (ok, data) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function play(uint amount) public {
        require(amount == 10);
        require(address(this).balance >= amount);
        uint b0 = address(this).balance;
        c.play{value: amount}();
        uint potAfter = c.pot();
        uint spent = b0 - address(this).balance;
        if (potAfter == 0) {
            assert(spent == amount - 1);
        }
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function t() public {
        uint amount = 10;
        require(address(this).balance >= amount);
        uint balBefore = address(this).balance;
        c.play{value: amount}();
        uint balAfter = address(this).balance;
        assert(c.pot() > 0 || balAfter > balBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amount) public {
        require(amount != 10);
        require(address(this).balance >= amount);
        try c.play{value: amount}() {
            assert(false);
        } catch {
            assert(c.pot() == 0);
        }
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function check(uint amount) public {
        require(amount == 10);
        require(address(this).balance >= amount);
        uint balanceBefore = address(this).balance;
        c.play{value: amount}();
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, address(this)))) % 2;
        assert(random != 0 || address(this).balance == balanceBefore - amount + 9);
    }

    receive() external payable {}
}
